// Handle both form trigger AND Google Sheets trigger
const input = $input.first().json;

// Form trigger sends 'Lead URL', Sheets trigger sends 'URL'
const url = input['Lead URL'] || input['URL'] || input['url'] || '';
const notes = input['Notes (optional)'] || input['Notes'] || input['notes'] || '';

if (url) throw new Error('No URL found in input — check trigger source');

let urlType = 'website';
if (url.includes('linkedin.com')) urlType = 'linkedin';
else if (url.includes('instagram.com')) urlType = 'instagram';
else if (url.includes('twitter.com') || url.includes('x.com')) urlType = 'twitter';

return [{ json: { url, notes, urlType } }];

// Truncate content to avoid token limits
const content = $input.first().json.data || $input.first().json.body || '';
const url = $('Detect URL Type').first().json.url;
const urlType = $('Detect URL Type').first().json.urlType;
const notes = $('Detect URL Type').first().json.notes;

// Keep first 6000 chars — enough for Llama to work with
const truncated = content.toString().slice(0, 6000);

return [{ json: { content: truncated, url, urlType, notes } }];

