// Parse Groq response safely
const response = $input.first().json;
const rawContent = response.choices[0].message.content;

let analysis;
try {
  // Strip any accidental markdown fences
  const cleaned = rawContent.replace(/```json|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch (e) {
  // Fallback if parsing fails so workflow doesn't break
  analysis = {
    company_name: 'Parse Error — Review Manually',
    what_they_do: rawContent.slice(0, 200),
    client_type: 'Unknown',
    priority: 'Cold',
    priority_reason: 'Could not analyze',
    gaps: [],
    pitches: [],
    email_subject: 'New Lead — Review Manually',
    email_body: 'Review manually — AI could not parse response.'
  };
}

// Flatten gaps and pitches into readable strings for ClickUp + email
const gapsText = (analysis.gaps || [])
  .map((g, i) => `${i + 1}. ${g.gap} (Evidence: ${g.evidence} | Impact: ${g.impact})`)
  .join('\n');

const pitchesText = (analysis.pitches || [])
  .map((p, i) => `${i + 1}. ${p.title} — ${p.description} [${p.skill_used}] → ${p.value}`)
  .join('\n');

const url = $('Detect URL Type').first().json.url;
const notes = $('Detect URL Type').first().json.notes;

return [{ json: { ...analysis, gapsText, pitchesText, url, notes } }];

